#!/usr/bin/env bash
# 1版目：主人公カノープスと相方ミラの基準イラスト（写真はコスチュームなので、生き物のキャラとして描き直す）
cd ~/Projects/canopus-dive
S="Cute anime-style kemono (furry) character illustration for an all-ages game, clean lineart, soft cel shading, glossy highlights, full body, front three-quarter view, standing. Draw it as a living cartoon creature character (NOT a costume, NOT inflatable, no seams, no valves). Modest, non-sexual, cheerful. Plain flat pure green (#00FF00) background, nothing else, no text."
gen(){ tools/gen_image.sh "$@" & }
gen art/raw/canopus_base.png "$S Character: CANOPUS, an energetic tomboyish girl who is an orca x dragon hybrid. Glossy dark slate-black skin with cream-white muzzle, chest and belly like an orca, bright yellow crescent markings on the hips and yellow stripe bands on the upper arms, big pointed ears with yellow rims and white insides, two small white horns, messy short silver-gray hair with bangs over one eye, amber eyes, a bright blue scarf around the neck, a thick orca tail with white underside, broad flipper-like forearms ending in small white claws, sturdy feet with three toes. Big confident grin, one fist raised. Use the reference photo only for colors and markings." art/raw/ref_canopus2.jpg
gen art/raw/mira_base.png "$S Character: MIRA, a shy small axolotl x dragon creature girl. Glossy periwinkle-blue skin, cream-white belly with a small pink heart mark on the chest, a round head with huge dark glossy eyes and two pink dots on the forehead, axolotl gill fronds on each side of the head, two long ear-like fronds on top with pink stripes and pink tips, pink bat-like dragon wings with cream bones, slim blue tail with pink tip, pink feet. No mouth line visible, expresses emotion with ears and wings; here she is waving one wing happily. Use the reference photo only for colors and markings." art/raw/ref_mira.jpg
wait
